CREATE VIEW catalog_model_records WITH (security_invoker=true) AS SELECT m.availability,m.row_id,m.organization_id,m.user_id,m.base_row_id,m.custom_fields,m.provider_catalog_id,m.id,m.name,m.display_name,m.description,m.service_kind,m.connections,m.headers,m.body_defaults,m.source_id AS research_id,m.route_selection,jsonb_build_object('input',CASE WHEN m.text_input_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('maxTokens',m.max_input_tokens),'pricing',NULL) ELSE jsonb_build_object('status',m.text_input_support) END,'output',CASE WHEN m.text_output_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('maxTokens',m.max_output_tokens,'thinking',CASE WHEN m.thinking_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('effortMapping','{}'::jsonb,'defaultEffort',m.thinking_default_effort,'budget',CASE WHEN m.thinking_budget_min IS NULL THEN NULL ELSE jsonb_build_object('minTokens',m.thinking_budget_min,'maxTokens',m.thinking_budget_max,'defaultTokens',m.thinking_budget_default) END),'pricing',NULL) ELSE jsonb_build_object('status',m.thinking_support) END),'pricing',NULL) ELSE jsonb_build_object('status',m.text_output_support) END) AS text,CASE WHEN m.vision_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('formats',CASE WHEN m.vision_formats_known THEN '[]'::jsonb ELSE NULL END,'maxImages',m.max_images),'pricing',NULL) ELSE jsonb_build_object('status',m.vision_support) END AS vision,CASE WHEN m.pdf_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('maxFiles',m.max_pdf_files,'maxPages',m.max_pdf_pages),'pricing',NULL) ELSE jsonb_build_object('status',m.pdf_support) END AS pdf,jsonb_build_object('input',CASE WHEN m.audio_input_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('formats',CASE WHEN m.audio_input_formats_known THEN '[]'::jsonb ELSE NULL END,'maxDurationMs',m.max_audio_input_duration_ms,'maxBytes',m.max_audio_input_bytes),'pricing',NULL) ELSE jsonb_build_object('status',m.audio_input_support) END,'output',CASE WHEN m.audio_output_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('formats',CASE WHEN m.audio_output_formats_known THEN '[]'::jsonb ELSE NULL END,'maxDurationMs',m.max_audio_output_duration_ms,'maxBytes',m.max_audio_output_bytes),'pricing',NULL) ELSE jsonb_build_object('status',m.audio_output_support) END) AS audio,CASE WHEN m.video_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('formats',CASE WHEN m.video_formats_known THEN '[]'::jsonb ELSE NULL END,'maxDurationMs',m.max_video_duration_ms,'maxFrames',m.max_video_frames),'pricing',NULL) ELSE jsonb_build_object('status',m.video_support) END AS video,CASE WHEN m.image_generation_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('formats',CASE WHEN m.image_generation_formats_known THEN '[]'::jsonb ELSE NULL END,'maxImages',m.max_generated_images),'pricing',NULL) ELSE jsonb_build_object('status',m.image_generation_support) END AS image_generation,jsonb_build_object('calling',CASE WHEN m.tool_calling_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('maxTools',m.max_tools),'pricing',NULL) ELSE jsonb_build_object('status',m.tool_calling_support) END,'forcedChoice',CASE WHEN m.forced_tool_choice_support='supported' THEN jsonb_build_object('status','supported','configuration','{}'::jsonb,'pricing',NULL) ELSE jsonb_build_object('status',m.forced_tool_choice_support) END,'parallelCalls',CASE WHEN m.parallel_tool_calls_support='supported' THEN jsonb_build_object('status','supported','configuration','{}'::jsonb,'pricing',NULL) ELSE jsonb_build_object('status',m.parallel_tool_calls_support) END) AS tools,CASE WHEN m.structured_output_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('jsonMode',CASE WHEN m.json_mode_support='supported' THEN jsonb_build_object('status','supported','configuration','{}'::jsonb,'pricing',NULL) ELSE jsonb_build_object('status',m.json_mode_support) END,'jsonSchema',CASE WHEN m.json_schema_support='supported' THEN jsonb_build_object('status','supported','configuration','{}'::jsonb,'pricing',NULL) ELSE jsonb_build_object('status',m.json_schema_support) END),'pricing',NULL) ELSE jsonb_build_object('status',m.structured_output_support) END AS structured_output,CASE WHEN m.search_support='supported' THEN jsonb_build_object('status','supported','configuration',jsonb_build_object('maxResults',m.max_search_results),'pricing',NULL) ELSE jsonb_build_object('status',m.search_support) END AS search,jsonb_build_object('contextTokens',m.context_tokens) AS limits,NULL::jsonb AS billing FROM catalog_model_book m;
GRANT SELECT ON catalog_model_records TO compallm_restricted;
